 public function test_maintenance_visits_older_plans_and_keeps_dirty_evidence_for_all_batches():void {
  $p=$this->setupProduct();$old=$this->plan($p);$copy=fn(array $extra)=>Plan::create(array_replace(['version'=>(string)\Illuminate\Support\Str::uuid(),'request_key'=>hash('sha256',uniqid()),'status'=>'OPTIMAL','scope'=>$old->scope,'input'=>$old->input,'result'=>$old->result,'evidence_cutoff'=>now(),'created_by'=>Auth::id()],$extra));
  for($n=0;$n<10;$n++)$copy(['approved'=>['alternative'=>'balanced'],'drafts'=>['purchase_requests'=>[],'transfers'=>[]]]);$new=$copy([]);
  $p->update(['quantity'=>10]);InventoryPlanningService::invalidate($p->company_id,[$p->id]);Cache::put('optimizer-dirty:'.$p->company_id,'first-change');
  $this->assertSame(1,app(Optimizer::class)->maintain());$this->assertSame('STALE',$old->fresh()->status);$this->assertSame('OPTIMAL',$new->fresh()->status);$this->assertTrue(Cache::has('optimizer-dirty:'.$p->company_id));
  $this->assertSame(1,app(Optimizer::class)->maintain());$this->assertSame('STALE',$new->fresh()->status);$this->assertFalse(Cache::has('optimizer-dirty:'.$p->company_id));
  $this->assertDatabaseCount('purchase_requests',0);$this->assertDatabaseCount('stock_movements',0);
 }
 public function test_new_dirty_generation_is_not_lost_when_an_older_sweep_finishes():void {
  $p=$this->setupProduct();$old=$this->plan($p);
  for($n=0;$n<11;$n++)Plan::create(['version'=>(string)\Illuminate\Support\Str::uuid(),'request_key'=>hash('sha256',uniqid()),'status'=>'OPTIMAL','scope'=>$old->scope,'input'=>$old->input,'result'=>$old->result,'evidence_cutoff'=>now(),'created_by'=>Auth::id(),'approved'=>['alternative'=>'balanced'],'drafts'=>['purchase_requests'=>[],'transfers'=>[]]]);
  Cache::put('optimizer-dirty:'.$p->company_id,'first-change');$this->assertSame(0,app(Optimizer::class)->maintain());
  Cache::put('optimizer-dirty:'.$p->company_id,'new-change');$this->assertSame(0,app(Optimizer::class)->maintain());$this->assertSame('new-change',Cache::get('optimizer-dirty:'.$p->company_id));
  $this->assertSame(0,app(Optimizer::class)->maintain());$this->assertSame(0,app(Optimizer::class)->maintain());$this->assertFalse(Cache::has('optimizer-dirty:'.$p->company_id));
 }
