  $p=$this->setupProduct();$plan=$this->plan($p,['product_ids'=>[]]);Product::create(['name'=>'New active product','sku'=>'OPT-NEW','category_id'=>$p->category_id,'unit'=>'pcs','quantity'=>10,'min_quantity'=>20,'price'=>5,'purchase_price'=>2]);
